-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.review_log (
  id bigint generated always as identity not null,
  user_id uuid default auth.uid() not null,
  action text not null,
  note_guid text not null,
  ord smallint not null,
  deck_id text not null,
  reviewed_at timestamp with time zone default now() not null,
  rating smallint,
  queue_before text,
  phase_before text not null,
  phase_after text not null,
  interval integer,
  last_interval integer,
  duration_ms integer,
  stability_after real,
  difficulty_after real,
  r_before real,
  card_version smallint,
  study_day date not null,
  constraint review_log_pkey PRIMARY KEY (id),
  constraint review_log_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint review_log_action_check CHECK ((action = ANY (ARRAY['answer'::text, 'bury_card'::text, 'bury_note'::text, 'suspend_card'::text, 'suspend_note'::text, 'flag'::text, 'unbury'::text, 'unsuspend'::text, 'forget'::text]))),
  constraint review_log_card_version_check CHECK (((card_version >= 1) AND (card_version <= 32767))),
  constraint review_log_check CHECK (((rating IS NULL) = (queue_before IS NULL))),
  constraint review_log_check1 CHECK (((rating IS NULL) OR (action = 'answer'::text))),
  constraint review_log_deck_id_check CHECK ((deck_id ~ '^[0-9]{1,20}$'::text)),
  constraint review_log_duration_ms_check CHECK (((duration_ms >= 0) AND (duration_ms <= 7200000))),
  constraint review_log_note_guid_check CHECK ((note_guid ~ '^[\x21-\x7e]{1,64}$'::text)),
  constraint review_log_ord_check CHECK (((ord >= 0) AND (ord <= 9999))),
  constraint review_log_phase_after_check CHECK ((phase_after = ANY (ARRAY['new'::text, 'learning'::text, 'review'::text, 'relearning'::text]))),
  constraint review_log_phase_before_check CHECK ((phase_before = ANY (ARRAY['new'::text, 'learning'::text, 'review'::text, 'relearning'::text]))),
  constraint review_log_queue_before_check CHECK ((queue_before = ANY (ARRAY['new'::text, 'learn'::text, 'day_learn'::text, 'review'::text]))),
  constraint review_log_r_before_check CHECK (((r_before >= (0)::double precision) AND (r_before <= (1)::double precision))),
  constraint review_log_rating_check CHECK (((rating >= 1) AND (rating <= 4)))
);

CREATE INDEX review_log_user_time ON public.review_log USING btree (user_id, reviewed_at);

CREATE TRIGGER quota_changes AFTER INSERT ON public.review_log FOR EACH ROW EXECUTE FUNCTION public.quota_changes();
CREATE TRIGGER review_log_set_day BEFORE INSERT ON public.review_log FOR EACH ROW EXECUTE FUNCTION public.review_log_set_day();
CREATE TRIGGER study_days_count AFTER INSERT OR DELETE ON public.review_log FOR EACH ROW EXECUTE FUNCTION public.study_days_count();

alter table public.review_log enable row level security;

create policy "delete own log" on public.review_log
  as permissive
  for delete
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "insert own log" on public.review_log
  as permissive
  for insert
  to authenticated
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "read own log" on public.review_log
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.review_log to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.review_log to service_role;
